def gen(rng):
    def make(n, shape, maxd=5000, vlo=-10**9, vhi=10**9, chain=0):
        V = [rng.randint(vlo, vhi) for _ in range(n)]
        L = [-1] * n
        R = [-1] * n
        dep = [1] * n
        if shape == 'heap':
            for i in range(n):
                if 2 * i + 1 < n:
                    L[i] = 2 * i + 1
                    dep[2 * i + 1] = dep[i] + 1
                if 2 * i + 2 < n:
                    R[i] = 2 * i + 2
                    dep[2 * i + 2] = dep[i] + 1
            return V, L, R
        cand = []
        start = 1
        if shape in ('left', 'right', 'zig'):
            for i in range(1, n):
                side = 0 if shape == 'left' else (1 if shape == 'right' else (i % 2))
                if side == 0:
                    L[i - 1] = i
                else:
                    R[i - 1] = i
                dep[i] = dep[i - 1] + 1
            return V, L, R
        if chain:
            for i in range(1, chain):
                if rng.random() < 0.5:
                    L[i - 1] = i
                else:
                    R[i - 1] = i
                dep[i] = dep[i - 1] + 1
            cand = [i for i in range(chain) if (L[i] < 0 or R[i] < 0) and dep[i] < maxd]
            start = chain
        else:
            cand = [0]
        for i in range(start, n):
            k = rng.randrange(len(cand))
            u = cand[k]
            free = [s for s in (0, 1) if (L[u] if s == 0 else R[u]) < 0]
            s = rng.choice(free)
            if s == 0:
                L[u] = i
            else:
                R[u] = i
            dep[i] = dep[u] + 1
            if len(free) == 1:
                cand[k] = cand[-1]
                cand.pop()
            if dep[i] < maxd:
                cand.append(i)
        return V, L, R

    def ser(V, L, R):
        toks = [str(V[0])]
        q = [0]
        h = 0
        while h < len(q):
            u = q[h]
            h += 1
            for ch in (L[u], R[u]):
                if ch < 0:
                    toks.append('null')
                else:
                    toks.append(str(V[ch]))
                    q.append(ch)
        while toks[-1] == 'null':
            toks.pop()
        return ' '.join(toks)

    tests = ["1", "0 null 1", "5 4", "-1000000000 1000000000 -1000000000", "3 2 null 1", "1 null 2 null 3 null 4"]
    for _ in range(50):
        n = rng.randint(1, 14)
        tests.append(ser(*make(n, 'random', vlo=-9, vhi=9)))
    for shape in ('left', 'right', 'zig', 'heap'):
        tests.append(ser(*make(12, shape, vlo=-99, vhi=99)))
    tests.append(ser(*make(5000, 'left', vlo=-1000, vhi=1000)))
    tests.append(ser(*make(5000, 'right', vlo=-1000, vhi=1000)))
    tests.append(ser(*make(5000, 'zig')))
    tests.append(ser(*make(20000, 'random')))
    tests.append(ser(*make(100000, 'random')))
    tests.append(ser(*make(100000, 'heap', vlo=-1000, vhi=1000)))
    tests.append(ser(*make(100000, 'random', vlo=-1000, vhi=1000, chain=5000)))
    tests.append(ser(*make(100000, 'random', vlo=-1000, vhi=1000, chain=3000)))
    return tests
